#include <iostream>
#include <array>

int main() {
    // Declare a compile-time fixed-size array of 4 integers
    std::array<int, 4> values{}; // Value-initialized to 0

    std::cout << "Array size: " << values.size() << "\n";
    std::cout << "Initial element 0: " << values[0] << "\n";

    values[0] = 42;
    std::cout << "Updated element 0: " << values[0] << "\n";
    return 0;
}

#include <iostream>
#include <array>
#include <cstddef>

int main() {
    std::array<int, 5> numbers{10, 20, 30, 40, 50};

    // Using subscript expression as an lvalue
    std::size_t offset_a = 1;
    std::size_t offset_b = 2;
    numbers[offset_a + offset_b] += 5; // Modifies numbers[3], which is the 4th element

    std::cout << "Element at index 3: " << numbers[3] << "\n";

    // Demonstrating the 1st element vs element at index 1
    std::cout << "First element (index 0): " << numbers[0] << "\n";
    std::cout << "Second element (index 1): " << numbers[1] << "\n";
    return 0;
}
